insert into public.quotes (date, text, author) values ('2025-12-25', 'Seseorang bertanya kepadaku. "Kamu selalu ada untuk semua orang, tetapi ketika kamu butuh seseorang, siapa yang ada untukmu?".', 'Phion Rushandle');

